import socket
def banner(host, port, send):
    try:
        s = socket.create_connection((host, port), timeout=8)
        if send:
            s.sendall(send)
        r = s.recv(300)
        s.close()
        return repr(r[:200])
    except Exception as e:
        return f"ERR {type(e).__name__}: {e}"

